// WRONG: Deprecation without removal
/** @deprecated Use newFunction instead */
export function oldFunction() { ... }
export function newFunction() { ... }

// CORRECT: Just the new function, old one deleted
export function newFunction() { ... }
// All callers updated directly

// WRONG: Backwards compatibility wrapper
export function loadConfig(path: string) {
  // Support old format for backwards compatibility
  if (isOldFormat(path)) {
    return loadOldConfig(path);
  }
  return loadNewConfig(path);
}

// WRONG: Monolithic orchestrator handling multiple domains
// extension.ts - 500+ lines
export function activate(context) {
  // Task domain logic...
  // Quick domain logic...
  // Docs domain logic...
  // Config domain logic...
  // Terminal domain logic...
}

// CORRECT: Decomposed into domain orchestrators
// extension.ts - thin composition root (~100 lines)
import { createTasksOrchestrator } from './orchestrators/tasks.orchestrator';
import { createQuicksOrchestrator } from './orchestrators/quicks.orchestrator';

export function activate(context) {
  const tasksOrch = createTasksOrchestrator(deps);
  const quicksOrch = createQuicksOrchestrator(deps);
  // Wire orchestrators to VSCode commands/views
}

// CORRECT: Domain orchestrator structure
// orchestrators/tasks.orchestrator.ts
export function createTasksOrchestrator(deps: TasksOrchestratorDeps) {
  const taskParser = createTaskParserComputer();
  const tasksView = createTasksViewCapability({ ... });

  function handleRunAction(action: TaskAction): void {
    // Policy: when/whether to run
    const command = buildCommand(action, shouldUseYoloMode());
    deps.terminal.sendCommand(command);
  }

  return { treeProvider: tasksView.createTreeDataProvider(), handleRunAction };
}

// WRONG: Orchestrator importing another orchestrator
// orchestrators/tasks.orchestrator.ts
import { createQuicksOrchestrator } from './quicks.orchestrator';

export function createTasksOrchestrator(deps) {
  const quicksOrch = createQuicksOrchestrator(deps);  // Forbidden!
